package run.ikaros.finance; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class BalanceSnapshotService{private final LedgerRepository ledgers;private final AccountRepository accounts;private final BalanceSnapshotRepository snapshots;public BalanceSnapshotService(LedgerRepository l,AccountRepository a,BalanceSnapshotRepository s){ledgers=l;accounts=a;snapshots=s;}public Mono<BalanceSnapshotView> create(UUID actor,UUID ledgerId,CreateBalanceSnapshotRequest q){return own(actor,ledgerId).flatMap(ledger->accounts.findById(q.accountId()).filter(account->account.ownerId().equals(actor)&&account.ledgerId().equals(ledgerId)).switchIfEmpty(Mono.error(new NotFoundException("Account 不存在或不属于该 Ledger"))).flatMap(account->snapshots.findByAccountIdAndOwnerIdAndSnapshotDate(q.accountId(),actor,q.snapshotDate()).flatMap(existing->Mono.<BalanceSnapshotEntity>error(new ConflictException("该账户该日期已存在快照"))).switchIfEmpty(snapshots.save(new BalanceSnapshotEntity(null,ledgerId,q.accountId(),actor,q.snapshotDate(),account.currentBalance(),account.currency(),Instant.now(),null))))).map(this::view);}public Flux<BalanceSnapshotView> list(UUID actor,UUID ledgerId){return own(actor,ledgerId).flatMapMany(ledger->snapshots.findAllByLedgerIdAndOwnerIdOrderBySnapshotDateDesc(ledgerId,actor).map(this::view));}private Mono<LedgerEntity> own(UUID actor,UUID ledgerId){return ledgers.findById(ledgerId).filter(ledger->ledger.ownerId().equals(actor)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权访问")));}private BalanceSnapshotView view(BalanceSnapshotEntity x){return new BalanceSnapshotView(x.id(),x.accountId(),x.snapshotDate(),x.balance(),x.currency(),x.createdAt());}}
